/** Generated by scaffold-crud-pages. Query hooks for Payments.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchPaymentsList,
  fetchPaymentsById,
  createPayments,
  updatePayments,
  deletePayments,
  type FetchPaymentsListParams,
} from '~/services/httpServices/paymentsService';
import type { CreatePaymentsRequest, UpdatePaymentsRequest } from '~/types/payments';

const DOMAIN = 'payments';

export function usePaymentsList(params?: FetchPaymentsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchPaymentsList(params),
  });
}

export function usePayments(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchPaymentsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreatePayments() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreatePaymentsRequest) => createPayments(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdatePayments() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdatePaymentsRequest }) =>
      updatePayments(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeletePayments() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deletePayments(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
